function pollWindow(at, saved, channel, mention) {
  if (!/^\d{17,20}$/.test(channel) || (mention && !/^\d{17,20}$/.test(mention))) {
    throw new Error("Configure a private Discord channel ID and optional user ID.");
  }
  const scheduled = Date.parse(at);
  if (!Number.isFinite(scheduled)) throw new Error("Missing schedule timestamp.");
  const now = Math.max(scheduled, Date.now());
  if (saved?.nextAt > now) return null;
  const before = Math.floor(now / 1000) * 1000;
  const since = saved?.since ?? before - 60000;
  return {
    key: "github-notifications:" + channel,
    channel,
    mention,
    now,
    before,
    since,
    query: {
      since: new Date(since).toISOString().replace(".000Z", "Z"),
      before: new Date(before).toISOString().replace(".000Z", "Z"),
      all: "false",
      per_page: "50",
    },
  };
}

const settings = {
  channel: "YOUR_DISCORD_CHANNEL_ID",
  mention: "",
};
const state = $getWorkflowStaticData("global");
const key = "github-notifications:" + settings.channel;
const window = pollWindow(
  $input.first().json.timestamp,
  state[key],
  settings.channel,
  settings.mention,
);
if (!window) return [];
state[key] = { since: window.since, nextAt: window.now + 60000 };
return [{ json: { window } }];

