function nextNotificationPage(headers) {
  const link = headers?.link ?? headers?.Link ?? "";
  for (const segment of link.split(/,(?=\s*<)/)) {
    if (!/;\s*rel="next"\s*$/i.test(segment)) continue;
    const match = /^\s*<https:\/\/api\.github\.com\/notifications\?([^<>]+)>\s*;/i.exec(segment);
    const pageText = match?.[1].match(/(?:^|&)page=(\d+)(?:&|$)/)?.[1];
    const page = Number(pageText);
    if (!Number.isSafeInteger(page) || page < 2)
      throw new Error("Unexpected GitHub pagination link.");
    return page;
  }
  return null;
}

function notificationLine(thread, window) {
  if (thread?.unread !== true) return null;
  const updated = Date.parse(thread.updated_at);
  if (!Number.isFinite(updated))
    throw new Error("GitHub returned a notification without a valid update date.");
  if (updated <= window.since || updated >= window.before) return null;
  const safeText = (text, length) =>
    String(text ?? "")
      .replace(/[\u0000-\u001f\u007f\u202a-\u202e\u2066-\u2069]/g, " ")
      .trim()
      .slice(0, length)
      .replace(/@/g, "@\u200b")
      .replace(/</g, "‹")
      .replace(/>/g, "›")
      .replace(/[\\`*_{}\[\]()#+.!|~]/g, "\\$&");
  const reason = safeText(thread.reason, 60) || "notification";
  const title = safeText(thread.subject?.title, 280) || "Untitled notification";
  const url = thread.subject?.url;
  const path =
    typeof url === "string" &&
    url.length <= 400 &&
    /^https:\/\/api\.github\.com\/repos\/([A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+)\/(.+)$/.exec(url);
  let link = "";
  if (
    path &&
    /^[A-Za-z0-9._~/-]+$/.test(path[2]) &&
    ![...path[1].split("/"), ...path[2].split("/")].some((x) => x === "." || x === "..")
  ) {
    const kind = /^(issues|pulls|discussions|commits)\/([A-Za-z0-9]+)$/.exec(path[2]);
    if (kind) {
      const route = {
        issues: "issues",
        pulls: "pull",
        discussions: "discussions",
        commits: "commit",
      }[kind[1]];
      link = "https://github.com/" + path[1] + "/" + route + "/" + kind[2];
    } else link = url;
  }
  if (typeof thread.id !== "string" || !thread.id)
    throw new Error("GitHub returned a notification without an ID.");
  return {
    id: thread.id + ":" + updated,
    line: "- [" + reason + "] " + title + (link ? " <" + link + ">" : ""),
  };
}

function readNotificationPage(previous, window, status, headers, body) {
  const state = previous ?? { page: 0, interval: 60, lines: [], ids: [] };
  const seconds = Number(headers?.["x-poll-interval"]);
  const retry = Number(headers?.["retry-after"]);
  const reset = Number(headers?.["x-ratelimit-reset"]) - Math.floor(window.now / 1000);
  const positive = (value) => (Number.isSafeInteger(value) && value > 0 ? value : 0);
  state.interval = Math.max(
    state.interval,
    positive(seconds),
    positive(retry),
    (status === 403 || status === 429) && headers?.["x-ratelimit-remaining"] === "0"
      ? positive(reset)
      : 0,
  );
  state.page++;
  state.more = false;
  if (status === 304 && state.page === 1) return state;
  if (status !== 200 || !Array.isArray(body)) {
    state.error = "GitHub notification read failed" + (status ? " (HTTP " + status + ")." : ".");
    return state;
  }
  try {
    const ids = new Set(state.ids);
    for (const thread of body) {
      const item = notificationLine(thread, window);
      if (!item || ids.has(item.id)) continue;
      ids.add(item.id);
      state.lines.push(item.line);
    }
    state.ids = [...ids];
    const next = nextNotificationPage(headers);
    if (next !== null && (next !== state.page + 1 || state.page >= 20)) {
      throw new Error("GitHub notification pagination did not complete.");
    }
    state.more = next !== null;
  } catch (cause) {
    state.error = cause.message;
  }
  return state;
}

function notificationCheckpoint(window, state) {
  return {
    since: state.error ? window.since : window.before - 1000,
    nextAt: Math.max(window.now, Date.now()) + state.interval * 1000,
  };
}

function discordBatches(window, lines) {
  if (!lines.length) return [];
  const split = [];
  let content =
    "Unread GitHub notifications" + (window.mention ? " <@" + window.mention + ">" : "") + ":";
  for (const line of lines) {
    if (content.length + line.length + 1 > 1900) {
      split.push(content);
      content = "Unread GitHub notifications (continued):";
    }
    content += "\n" + line;
  }
  split.push(content);
  return split.map((text, index) => ({
    content: text,
    allowed_mentions: { parse: [], users: index === 0 && window.mention ? [window.mention] : [] },
    flags: 4,
  }));
}

const window = $("Configure the inbox and destination").first().json.window;
let state = null;
for (const { json: page } of $input.all()) {
  state = readNotificationPage(state, window, page.statusCode, page.headers, page.body);
  if (state.error) break;
}
if (state.more) state.error = "GitHub notification pagination did not complete.";
$getWorkflowStaticData("global")[window.key] = notificationCheckpoint(window, state);
if (state.error) return [{ json: { status: "read_failed", errorMessage: state.error } }];
return discordBatches(window, state.lines).map((message) => ({ json: { message } }));

function discordConfirmed(reply, channel, content) {
  return (
    typeof reply?.id === "string" &&
    !!reply.id &&
    reply.channel_id === channel &&
    reply.content === content
  );
}

const channel = $("Configure the inbox and destination").first().json.window.channel;
const sent = $("Save the poll window").all();
return $input.all().map(({ json }, index) => ({
  json: {
    status:
      json.statusCode === 200 &&
      discordConfirmed(json.body, channel, sent[index]?.json.message?.content)
        ? "delivered"
        : "delivery_unconfirmed",
  },
}));
